def steps_for_plan(plan_id: str) -> list:
    """All real steps for one plan, already in the right execution order."""
    return [s for s in PLAN_STEPS if s["plan_id"] == plan_id]


def phases_for_plan(plan_id: str) -> list:
    """Real phases that actually have steps for this plan, in the real order."""
    present = {s["phase"] for s in steps_for_plan(plan_id)}
    return [p for p in PHASES if p in present]


def steps_for_phase(plan_id: str, phase: str) -> list:
    return [s for s in steps_for_plan(plan_id) if s["phase"] == phase]


def find_step(plan_id: str, phase: str, scenario: str) -> dict | None:
    return next((s for s in steps_for_phase(plan_id, phase) if s["scenario"] == scenario), None)


def find_plan_id(incident: str, cause: str) -> str | None:
    """Looks up which real plan (RW-01/02/03) matches a given incident+cause (by their real-world names)."""
    for pid, meta in PLAN_META.items():
        if meta["incident"] == incident and meta["cause"] == cause:
            return pid
    return None


# Our own Threat Profile catalog (cards/threat_map_v2_data.py's TAXONOMY)
# uses its own short IDs and slightly different wording for the same real
# incidents/causes (e.g. our "ransom"/"phish" vs the spreadsheet's "Data
# Encryption and Service Disruption"/"Phishing Email (...)")  -- this maps
# (module, threat_id, incident_id, cause_id) straight to a real plan_id, so
# the rest of the app never has to compare the two different wordings.
# Only 3 of our 10 threat/incident/cause combos have a real plan behind
# them yet (sir's spreadsheet only covers Ransomware so far) -- everything
# else intentionally has no entry here, so the card can honestly say "no real
# plan yet" instead of forcing a wrong match.
PLAN_ID_BY_TAXONOMY = {
    ("Cybersecurity", "ext", "ransom", "phish"): "RW-01",
    ("Cybersecurity", "ext", "ransom", "rdp"): "RW-02",
    ("Cybersecurity", "ext", "ato", "stuff"): "RW-03",
}


def find_plan_id_for_taxonomy(module: str, threat_id: str, incident_id: str, cause_id: str) -> str | None:
    return PLAN_ID_BY_TAXONOMY.get((module, threat_id, incident_id, cause_id))


def parse_form_instructions(instructions: str) -> list:
    """
    Parses the "form" response_type's mini-DSL into real fields:
    "Label:dropdown:OptA,OptB | Label2:dropdown-multiple:OptA,OptB | Label3:textarea"
    -> [{"label": ..., "type": "dropdown"|"dropdown-multiple"|"textarea", "options": [...] or None}, ...]
    """
    fields = []
    if not instructions:
        return fields
    for raw in instructions.split("|"):
        parts = raw.strip().split(":")
        if len(parts) < 2:
            continue
        label = parts[0].strip()
        field_type = parts[1].strip()
        options = [o.strip() for o in parts[2].split(",")] if len(parts) > 2 else None
        fields.append({"label": label, "type": field_type, "options": options})
    return fields
